// Garde les tickets NOUVEAU et construit le payload /analyze.
// IMPORTANT: /api/decisions/analyze exige 6 champs (typePiece, typeSinistre,
// ageVehiculeAns, kilometrage, categorieClient en plus du ticketId) avec des
// CODES DE RÉFÉRENCE valides. On extrait depuis la description, sinon défauts.
const data = $input.first().json;
const tickets = (data.content || data || []).filter(t => t.statut === 'NOUVEAU');
const MAX = 3; // limite pour une démo rapide ; augmenter en production

// Codes valides (rules-service /reference-items)
const PIECES = { moteur:'MECANIQUE', mecanique:'MECANIQUE', frein:'FREINAGE', embrayage:'TRANSMISSION', boite:'TRANSMISSION', transmission:'TRANSMISSION', carrosserie:'CARROSSERIE', 'pare-choc':'CARROSSERIE', alternateur:'ELECTRIQUE', batterie:'ELECTRIQUE', electr:'ELECTRIQUE', pneu:'PNEUMATIQUE', vitre:'VITRAGE', glace:'VITRAGE', clim:'CLIMATISATION', suspension:'SUSPENSION', hydraulique:'HYDRAULIQUE' };
const SINISTRES = { accident:'ACCIDENT', collision:'ACCIDENT', choc:'ACCIDENT', vol:'VOL', incendie:'INCENDIE', feu:'INCENDIE', panne:'PANNE', usure:'USURE', vandalisme:'VANDALISME', bris:'BRIS_GLACE' };
const CLIENTS = { entreprise:'PROFESSIONNEL', professionnel:'PROFESSIONNEL', flotte:'FLOTTE', premium:'PREMIUM', vip:'VIP' };

function detect(desc, map, def) {
  const d = (desc || '').toLowerCase();
  for (const k in map) { if (d.includes(k)) return map[k]; }
  return def;
}
function detectNum(desc, rx, def) {
  const m = (desc || '').match(rx);
  return m ? parseInt(m[1], 10) : def;
}

return tickets.slice(0, MAX).map(t => {
  const desc = t.description || t.transcription || '';
  return { json: {
    ticketId: t.id,
    numero: t.numero || 'N/A',
    clientNom: t.clientNom || 'Client',
    clientEmail: t.clientEmail || '',
    description: desc,
    typePiece: detect(desc, PIECES, 'AUTRE'),
    typeSinistre: detect(desc, SINISTRES, 'PANNE'),
    categorieClient: detect(desc, CLIENTS, 'STANDARD'),
    ageVehiculeAns: detectNum(desc, /(\d+)\s*ans?/, 5),
    kilometrage: detectNum(desc, /(\d+)\s*km/, 100000)
  }};
});

// Combine chaque ticket avec sa décision et détermine la route.
// Un échec d'analyse (HTTP 400 sur certaines combinaisons de règles) est traité
// comme 'à étudier' grâce à continueOnFail sur le nœud précédent.
const tickets = $('Filtrer NOUVEAU + extraire').all();
const decisions = $input.all();

return tickets.map((t, i) => {
  const tj = t.json;
  const dj = (decisions[i] || {}).json || {};
  const decision = dj.decision || dj.finalDecision || 'ETUDE';
  const tranchee = (decision === 'FAVORABLE' || decision === 'DEFAVORABLE') && !!dj.decisionId;
  return { json: {
    ticketId: tj.ticketId,
    numero: tj.numero,
    clientNom: tj.clientNom,
    clientEmail: tj.clientEmail,
    decisionId: dj.decisionId || '',
    decision: decision,
    score: (dj.score != null ? dj.score : null),
    source: dj.source || '',
    motif: dj.motif || dj.overrideMotif || 'Analyse automatique impossible — revue manuelle requise',
    route: tranchee ? 'tranchee' : 'etude'
  }};
});
